import assert from 'node:assert/strict';
import {execFile} from 'node:child_process';
import {promisify} from 'node:util';
import test from 'node:test';
import {createBalanceClient} from './src/client.mjs';
import {singleFlight} from './src/pending.mjs';
import {resolveBalance} from './src/resolve.mjs';

function deferred() {
  let resolve;
  let reject;
  const promise = new Promise((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return {promise, resolve, reject};
}

test('same pair shares the identical pending Promise and forwards original strings', async () => {
  const request = deferred();
  const calls = [];
  const get = createBalanceClient((...args) => {
    calls.push(args);
    return request.promise;
  });
  const first = get(' tenant:一 ', 'account:02');
  assert.ok(first instanceof Promise);
  assert.strictEqual(get(' tenant:一 ', 'account:02'), first);
  await Promise.resolve();
  assert.deepEqual(calls, [[' tenant:一 ', 'account:02']]);
  const balance = {balanceMinor: 0, currency: 'JPY'};
  request.resolve(balance);
  assert.strictEqual(await first, balance);
});

test('ordered tenant/account pairs remain independent, including delimiter collisions', async () => {
  const pairs = [
    ['tenant-one', 'shared'], ['tenant-two', 'shared'],
    ['tenant-one', 'another'],
    ['a:b', 'c'], ['a', 'b:c'], ['c', 'a:b'],
    ['', ':'], [':', ''], ['', ''],
    ['a"', '\\b'], ['a', '"\\b'],
  ];
  const calls = [];
  const requests = pairs.map(() => deferred());
  const get = createBalanceClient((...args) => {
    const index = pairs.findIndex(pair => pair[0] === args[0] && pair[1] === args[1]);
    calls.push(args);
    return requests[index].promise;
  });
  const promises = pairs.map(pair => get(...pair));
  assert.equal(new Set(promises).size, pairs.length);
  pairs.forEach((pair, index) => assert.strictEqual(get(...pair), promises[index]));
  await Promise.resolve();
  assert.deepEqual(calls, pairs);
  requests.forEach((request, index) => request.resolve({balanceMinor: index, currency: 'EUR'}));
  assert.deepEqual(await Promise.all(promises), pairs.map((_, index) => ({balanceMinor: index, currency: 'EUR'})));
});

test('settling one pair does not clear another pair’s pending request', async () => {
  const requests = [deferred(), deferred(), deferred()];
  let calls = 0;
  const get = createBalanceClient(() => requests[calls++].promise);
  const first = get('one', 'shared');
  const other = get('two', 'shared');
  requests[0].resolve(10);
  assert.equal(await first, 10);
  assert.strictEqual(get('two', 'shared'), other);
  const reload = get('one', 'shared');
  assert.notStrictEqual(reload, first);
  requests[1].resolve(20);
  requests[2].resolve(30);
  assert.deepEqual(await Promise.all([other, reload]), [20, 30]);
  assert.equal(calls, 3);
});

test('plain values return Promises and fulfilled values are never cached', async () => {
  let calls = 0;
  const get = createBalanceClient(() => ++calls);
  const first = get('t', 'a');
  assert.ok(first instanceof Promise);
  assert.strictEqual(get('t', 'a'), first);
  assert.equal(await first, 1);
  const second = get('t', 'a');
  assert.notStrictEqual(second, first);
  assert.equal(await second, 2);
  assert.equal(await get('t', 'a'), 3);
});

test('asynchronous rejection preserves its reason and allows a fresh request', async () => {
  const request = deferred();
  const reason = new Error('load failed');
  let calls = 0;
  const get = createBalanceClient(() => ++calls === 1 ? request.promise : 42);
  const first = get('t', 'a');
  assert.strictEqual(get('t', 'a'), first);
  const rejected = assert.rejects(first, error => error === reason);
  request.reject(reason);
  await rejected;
  const retry = get('t', 'a');
  assert.notStrictEqual(retry, first);
  assert.equal(await retry, 42);
  assert.equal(calls, 2);
});

test('synchronous throws become shared rejected Promises and allow retry', async () => {
  const reason = new Error('synchronous failure');
  let calls = 0;
  const get = createBalanceClient(() => {
    if (++calls === 1) throw reason;
    return 17;
  });
  let first;
  assert.doesNotThrow(() => { first = get('t', 'a'); });
  assert.ok(first instanceof Promise);
  assert.strictEqual(get('t', 'a'), first);
  await assert.rejects(first, error => error === reason);
  assert.equal(await get('t', 'a'), 17);
  assert.equal(calls, 2);
});

test('thenables are assimilated and failures permit retry', async () => {
  const reason = {message: 'thenable failure'};
  let calls = 0;
  const get = createBalanceClient(() => ++calls === 1
    ? {then(resolve, reject) { reject(reason); }}
    : {then(resolve) { resolve(91); }});
  await assert.rejects(get('t', 'a'), error => error === reason);
  assert.equal(await get('t', 'a'), 91);
});

test('singleFlight preserves its exported keyed, variadic interface', async () => {
  const request = deferred();
  const calls = [];
  const get = singleFlight((...args) => {
    calls.push(args);
    return request.promise;
  });
  const first = get('key', 'tenant', 'account');
  assert.strictEqual(get('key', 'ignored'), first);
  await Promise.resolve();
  assert.deepEqual(calls, [['tenant', 'account']]);
  request.resolve(6);
  assert.equal(await first, 6);
  const next = get('key', 'new', 'arguments');
  assert.notStrictEqual(next, first);
  assert.equal(await next, 6);
  assert.deepEqual(calls[1], ['new', 'arguments']);
});

test('separate clients do not share pending requests', async () => {
  const first = createBalanceClient(() => 1)('t', 'a');
  const second = createBalanceClient(() => 2)('t', 'a');
  assert.notStrictEqual(first, second);
  assert.deepEqual(await Promise.all([first, second]), [1, 2]);
});

test('resolver preserves minor units, currency, and identifiers exactly', async () => {
  const values = [
    {balanceMinor: 0, currency: 'JPY'},
    {balanceMinor: -0, currency: 'USD'},
    {balanceMinor: -12345, currency: 'EUR'},
    {balanceMinor: 12345, currency: 'KWD'},
    {balanceMinor: Number.MAX_SAFE_INTEGER, currency: 'CHF'},
    {balanceMinor: Number.MIN_SAFE_INTEGER, currency: 'GBP'},
  ];
  for (const value of values) {
    const get = createBalanceClient(() => value);
    assert.deepEqual(await resolveBalance(get, ' tenant ', 'account:一'), {
      tenant: ' tenant ', account: 'account:一', ...value,
    });
  }
});

test('resolver propagates client errors unchanged', async () => {
  const reason = new Error('unavailable');
  await assert.rejects(resolveBalance(() => Promise.reject(reason), 't', 'a'), error => error === reason);
  await assert.rejects(resolveBalance(() => { throw reason; }, 't', 'a'), error => error === reason);
});

test('handled loader failures create no extra unhandled rejection', async () => {
  const moduleURL = new URL('./src/client.mjs', import.meta.url).href;
  const script = `
    import assert from 'node:assert/strict';
    import {createBalanceClient} from ${JSON.stringify(moduleURL)};
    for (const load of [
      () => Promise.reject(new Error('async failure')),
      () => { throw new Error('sync failure'); },
    ]) {
      const get = createBalanceClient(load);
      await assert.rejects(get('t', 'a'));
      await new Promise(resolve => setImmediate(resolve));
      await assert.rejects(get('t', 'a'));
      await new Promise(resolve => setImmediate(resolve));
    }
  `;
  const {stderr} = await promisify(execFile)(process.execPath, [
    '--unhandled-rejections=strict', '--input-type=module', '-e', script,
  ]);
  assert.equal(stderr, '');
});

