import {singleFlight} from './pending.mjs';

export function createBalanceClient(load) {
  const get = singleFlight(load);
  // Encoding the ordered pair avoids collisions even when strings contain ':'.
  return (tenant, account) => get(JSON.stringify([tenant, account]), tenant, account);
}

artifacts.src/pending.mjs:
export function singleFlight(load) {
  const pending = new Map();
  return (key, ...args) => {
    if (pending.has(key)) return pending.get(key);

    // Defer invocation so synchronous throws reject and the entry exists first.
    const promise = Promise.resolve()
      .then(() => load(...args))
      .then(
        value => {
          pending.delete(key);
          return value;
        },
        error => {
          pending.delete(key);
          throw error;
        },
      );
    // Return the cleanup chain itself; no detached rejection is left behind.
    pending.set(key, promise);
    return promise;
  };
}

