artifacts.src/pending.mjs:
export function singleFlight(load) {
  const pending = new Map();
  return (key, ...args) => {
    if (pending.has(key)) return pending.get(key);

    // Defer invocation so synchronous throws reject and the entry exists before load runs.
    const p = Promise.resolve().then(() => load(...args)).then(
      value => {
        pending.delete(key);
        return value;
      },
      error => {
        pending.delete(key);
        throw error;
      },
    );
    pending.set(key, p);
    return p;
  };
}

