import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {test} from 'node:test';
import {createBalanceClient} from './src/client.mjs';
import {singleFlight} from './src/pending.mjs';
import {resolveBalance} from './src/resolve.mjs';

function deferred() {
  let resolve;
  let reject;
  const promise = new Promise((yes, no) => {
    resolve = yes;
    reject = no;
  });
  return {promise, resolve, reject};
}

test('same pair shares a pending Promise; fulfillment triggers a fresh load', async () => {
  const first = deferred();
  const value = {balanceMinor: 50, currency: 'EUR'};
  const calls = [];
  const client = createBalanceClient((...args) => {
    calls.push(args);
    return calls.length === 1 ? first.promise : value;
  });
  const pending = client('tenant', 'account');
  assert.ok(pending instanceof Promise);
  assert.strictEqual(client('tenant', 'account'), pending);
  first.resolve(value);
  assert.strictEqual(await pending, value);
  const next = client('tenant', 'account');
  assert.notStrictEqual(next, pending);
  assert.strictEqual(await next, value);
  assert.deepEqual(calls, [['tenant', 'account'], ['tenant', 'account']]);
});

test('ordered tenant/account pairs are isolated and passed through unchanged', async () => {
  const pairs = [
    ['tenant-one', 'shared'], ['tenant-two', 'shared'],
    ['same-tenant', 'one'], ['same-tenant', 'two'],
    ['a:b', 'c'], ['a', 'b:c'], ['c', 'a:b'],
    ['', ':'], [':', ''], ['租户:"\\', '账户\n'],
  ];
  const gate = deferred();
  const calls = [];
  const client = createBalanceClient((tenant, account) => {
    calls.push([tenant, account]);
    return gate.promise.then(() => ({tenant, account}));
  });
  const requests = pairs.map(pair => client(...pair));
  gate.resolve();
  const values = await Promise.all(requests);
  assert.equal(new Set(requests).size, pairs.length);
  pairs.forEach((pair, i) => {
    assert.deepEqual(values[i], {tenant: pair[0], account: pair[1]});
  });
  assert.deepEqual(calls, pairs);
});

test('settling one pair leaves another pair pending', async () => {
  const gates = {one: deferred(), two: deferred()};
  const client = createBalanceClient((tenant, account) => gates[account].promise);
  const one = client('tenant', 'one');
  const two = client('tenant', 'two');
  gates.one.resolve(1);
  assert.equal(await one, 1);
  assert.strictEqual(client('tenant', 'two'), two);
  gates.two.resolve(2);
  assert.equal(await two, 2);
});

test('plain values still share a Promise and are never persisted', async () => {
  let calls = 0;
  const client = createBalanceClient(() => ++calls);
  const first = client('t', 'a');
  assert.ok(first instanceof Promise);
  assert.strictEqual(client('t', 'a'), first);
  assert.equal(await first, 1);
  assert.equal(await client('t', 'a'), 2);
});

test('synchronous throws become shared rejections and allow retry', async () => {
  const error = new Error('synchronous failure');
  let calls = 0;
  const client = createBalanceClient(() => {
    if (++calls === 1) throw error;
    return 0;
  });
  const first = client('t', 'a');
  assert.ok(first instanceof Promise);
  assert.strictEqual(client('t', 'a'), first);
  await assert.rejects(first, reason => reason === error);
  assert.equal(await client('t', 'a'), 0);
  assert.equal(calls, 2);
});

test('rejection propagates unchanged, clears the entry, and has no orphan rejection', () => {
  // A strict child process makes any extra unhandled rejection fail this test.
  const moduleUrl = new URL('./src/client.mjs', import.meta.url).href;
  const result = spawnSync(process.execPath, [
    '--unhandled-rejections=strict', '--input-type=module', '--eval', `
      import assert from 'node:assert/strict';
      import {createBalanceClient} from ${JSON.stringify(moduleUrl)};
      const error = new Error('load failed');
      let calls = 0;
      let reject;
      const source = new Promise((resolve, no) => { reject = no; });
      const client = createBalanceClient(() => ++calls === 1 ? source : 42);
      const first = client('t', 'a');
      assert.strictEqual(client('t', 'a'), first);
      const checked = assert.rejects(first, reason => reason === error);
      await Promise.resolve();
      reject(error);
      await checked;
      await new Promise(resolve => setImmediate(resolve));
      const next = client('t', 'a');
      assert.notStrictEqual(next, first);
      assert.equal(await next, 42);
      assert.equal(calls, 2);
    `,
  ], {encoding: 'utf8', timeout: 10000});
  assert.ifError(result.error);
  assert.equal(result.status, 0, result.stderr || result.stdout);
});

test('singleFlight preserves its key and loader-arguments interface', async () => {
  const key = {};
  const calls = [];
  const get = singleFlight((...args) => {
    calls.push(args);
    return args;
  });
  const first = get(key, 'tenant', 'account');
  assert.strictEqual(get(key, 'ignored while pending'), first);
  assert.deepEqual(await first, ['tenant', 'account']);
  assert.deepEqual(await get(key, 'fresh'), ['fresh']);
  assert.deepEqual(calls, [['tenant', 'account'], ['fresh']]);
});

test('separate clients never share pending entries', async () => {
  const one = createBalanceClient(() => 1);
  const two = createBalanceClient(() => 2);
  assert.deepEqual(await Promise.all([one('t', 'a'), two('t', 'a')]), [1, 2]);
});

test('resolver preserves minor units, currency, and request identity', async () => {
  for (const balanceMinor of [0, -0, -125, 125, Number.MAX_SAFE_INTEGER, Number.MIN_SAFE_INTEGER]) {
    for (const currency of ['EUR', 'JPY', 'KWD']) {
      const value = Object.freeze({balanceMinor, currency});
      const client = createBalanceClient(() => value);
      assert.deepEqual(await resolveBalance(client, '租户', 'account:one'), {
        tenant: '租户', account: 'account:one', balanceMinor, currency,
      });
    }
  }
});

test('resolver propagates the original load error', async () => {
  const error = new Error('balance unavailable');
  const client = createBalanceClient(() => { throw error; });
  await assert.rejects(resolveBalance(client, 't', 'a'), reason => reason === error);
